import re
from xml.dom import Node, minidom
from xml.parsers.expat import ExpatError

MAX_BYTES = 1024 * 1024
MAX_DEPTH = 200

def start_tag(node):
    text = node.cloneNode(False).toxml()
    return text[:-2] + ">" if text.endswith("/>") else text

def check_depth(root):
    stack = [(root, 0)]
    while stack:
        node, depth = stack.pop()
        if depth > MAX_DEPTH:
            raise ValueError("XML nesting is too deep")
        stack.extend(
            (child, depth + 1)
            for child in node.childNodes
            if child.nodeType == Node.ELEMENT_NODE
        )

def render_element(node, depth):
    significant_text = any(
        child.nodeType == Node.CDATA_SECTION_NODE
        or (child.nodeType == Node.TEXT_NODE and child.data.strip())
        for child in node.childNodes
    )
    if significant_text:
        return "  " * depth + node.toxml()

    children = [
        child
        for child in node.childNodes
        if child.nodeType != Node.TEXT_NODE or child.data.strip()
    ]
    if not children:
        return "  " * depth + node.toxml()

    indent = "  " * depth
    lines = [indent + start_tag(node)]
    for child in children:
        if child.nodeType == Node.ELEMENT_NODE:
            lines.append(render_element(child, depth + 1))
        else:
            child_indent = "  " * (depth + 1)
            lines.extend(child_indent + line for line in child.toxml().splitlines())
    lines.append(indent + f"</{node.tagName}>")
    return "\n".join(lines)

def process(data):
    text = data["selection"]
    if not text.strip():
        raise ValueError("XML input is empty")
    if len(text.encode("utf-8", "surrogatepass")) > MAX_BYTES:
        raise ValueError("XML input exceeds 1 MiB")

    source = text[1:] if text.startswith("\ufeff") else text
    scan = re.sub(r"<!--.*?-->|<!\[CDATA\[.*?\]\]>", "", source, flags=re.DOTALL)
    if re.search(r"<!\s*(?:DOCTYPE|ENTITY)\b", scan, flags=re.IGNORECASE):
        raise ValueError(
            "DTD and entity declarations are not supported"
        )

    try:
        document = minidom.parseString(source)
    except ExpatError as error:
        raise ValueError(f"Invalid XML: {error}") from error

    check_depth(document.documentElement)
    declaration = re.match(r"\s*(<\?xml\s+.*?\?>)", source, flags=re.DOTALL | re.IGNORECASE)
    lines = [declaration.group(1)] if declaration else []
    for child in document.childNodes:
        if child.nodeType == Node.ELEMENT_NODE:
            lines.append(render_element(child, 0))
        elif child.nodeType in (Node.COMMENT_NODE, Node.PROCESSING_INSTRUCTION_NODE):
            lines.extend(child.toxml().splitlines())
    return "\n".join(lines)
